create or replace function public.superadmin_trocar_times_partida(p_match_id uuid,p_team_home smallint,p_team_away smallint) returns public.pelada_partidas language plpgsql security definer set search_path='' as $$ declare v_match public.pelada_partidas; v_queue smallint[]; v_old_home smallint; v_old_away smallint; begin if not public.is_superadmin() then raise exception 'Acesso negado'; end if; select * into v_match from public.pelada_partidas where id=p_match_id for update; if not found then raise exception 'Partida não encontrada'; end if; if v_match.status<>'CREATED' then raise exception 'Os times só podem ser trocados antes de iniciar a partida'; end if; if p_team_home=p_team_away then raise exception 'Selecione dois times diferentes'; end if; if not exists(select 1 from public.pelada_times where pelada_id=v_match.pelada_id and time=p_team_home) or not exists(select 1 from public.pelada_times where pelada_id=v_match.pelada_id and time=p_team_away) then raise exception 'Time inválido'; end if; v_old_home=v_match.team_home; v_old_away=v_match.team_away; select team_queue into v_queue from public.pelada_controles where pelada_id=v_match.pelada_id for update; update public.pelada_partidas set team_home=p_team_home,team_away=p_team_away,updated_at=now() where id=p_match_id returning * into v_match; update public.pelada_controles set team_queue=array(select team from(select team,min(ord) as position from unnest(coalesce(v_queue,'{}')||array[v_old_home,v_old_away]) with ordinality as queue_item(team,ord) where team<>p_team_home and team<>p_team_away group by team order by min(ord)) ordered_queue),updated_at=now() where pelada_id=v_match.pelada_id; return v_match; end $$;
